KEEP_APART_HEADER = ["first", "second", "note"]


# ---------------------------------------------------------------- settings

def load_settings(path: Path) -> dict:
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise DataError("settings", f"cannot read {path}: {e}") from None
    try:
        phone, email = doc["phone"], doc["email"]
        country, trunk = phone["country"], phone["trunk"]
        dotless, domain_aliases = email["dotless_domains"], email["domain_aliases"]
        ok = (isinstance(country, str) and isinstance(trunk, str) and isinstance(dotless, list)
              and all(isinstance(d, str) for d in dotless) and isinstance(domain_aliases, dict)
              and all(isinstance(k, str) and isinstance(v, str) for k, v in domain_aliases.items()))
    except (KeyError, TypeError):
        ok = False
    if not ok:
        raise DataError("settings", f"{path}: not the matching settings")
    return {"country": country, "trunk": trunk, "dotless": set(dotless), "domain_aliases": domain_aliases}


def load_keep_apart(path: Path) -> list[tuple[int, int]]:
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return []
    except (OSError, ValueError) as e:
        raise DataError("keep-apart", f"cannot read {path}: {e}") from None
    try:
        rows = list(csv.reader(io.StringIO(text, newline="")))
    except csv.Error as e:
        raise DataError("keep-apart", f"{path}: {e}") from None
    if not rows or rows[0] != KEEP_APART_HEADER:
        raise DataError("keep-apart", f"{path}: header is not {','.join(KEEP_APART_HEADER)}")
    out = []
    for n, row in enumerate(rows[1:], start=2):
        if len(row) != 3:
            raise DataError("keep-apart", f"{path}:{n}: expected 3 fields")
        a, b = ids.number(row[0]), ids.number(row[1])
        if a is None or b is None:
            raise DataError("keep-apart", f"{path}:{n}: not a member id")
        out.append((a, b))
    return out


def updated_instant(text: str) -> datetime:
    if not _UPDATED.match(text):
        raise ValueError(text)
    t = datetime.fromisoformat(text)
    if t.tzinfo is None:
        t = t.replace(tzinfo=timezone.utc)
    return t


# -------------------------------------------------------------------- keys

def name_key(text: str) -> str:
    t = unicodedata.normalize("NFKD", text)
    t = "".join(c for c in t if not unicodedata.category(c).startswith("M"))
    t = t.casefold()
    t = "".join(c if (c.isalpha() or c.isdigit()) else " " for c in t)
    return " ".join(t.split())


def email_key(text: str, settings: dict) -> str:
    t = text.strip().lower()
    if t.count("@") != 1:
        return ""
    local, domain = t.split("@")
    domain = settings["domain_aliases"].get(domain, domain)
    local = local.split("+", 1)[0]
    if domain in settings["dotless"]:
        local = local.replace(".", "")
    if not local or not domain:
        return ""
    return f"{local}@{domain}"


def phone_key(text: str, settings: dict) -> str:
    t = text.replace("(0)", "")
    t = "".join(c for c in t if c.isascii() and (c.isdigit() or c == "+"))
    if t.startswith("+"):
        rest = t[1:]
        if "+" in rest:
            return ""
        key = rest
    elif "+" in t:
        return ""
    elif t.startswith("00"):
        key = t[2:]
    elif t.startswith(settings["trunk"]):
        key = settings["country"] + t[len(settings["trunk"]):]
    else:
        return ""
    return key if 9 <= len(key) <= 15 else ""


