def plan(members: dict[int, dict], aliases: dict[int, int], settings: dict, keep_rows: list[tuple[int, int]]):
    """Returns (groups, refused). Each group is a dict; refused is a list of (low, high, rule)."""
    instants = {}
    for n, r in members.items():
