        except ValueError:
            raise DataError("members", f"member {r['id']}: bad updated value {r['updated']!r}") from None

    nums = sorted(members)
    nkey = {n: name_key(members[n]["name"]) for n in nums}
    ekey = {n: email_key(members[n]["email"], settings) for n in nums}
    pkey = {n: phone_key(members[n]["phone"], settings) for n in nums}
    dob = {n: dates.parse_day(members[n]["dob"]) for n in nums}
    given = {n: nkey[n].split(" ")[0] if nkey[n] else "" for n in nums}

    apart = set()
    for a, b in keep_rows:
        a, b = aliases.get(a, a), aliases.get(b, b)
        if a == b or a not in members or b not in members:
            continue
        apart.add((min(a, b), max(a, b)))

    def kept_apart(a, b):
        if dob[a] is not None and dob[b] is not None and dob[a] != dob[b]:
