        return d

    pairs: dict[tuple[int, int], int] = {}
    specs = [
        lambda n: (ekey[n], given[n]) if ekey[n] and given[n] else None,
        lambda n: (nkey[n], dob[n]) if nkey[n] and dob[n] is not None else None,
        lambda n: (nkey[n], pkey[n]) if nkey[n] and pkey[n] else None,
    ]
    for ri, spec in enumerate(specs):
        for bucket in buckets(spec).values():
            for i, a in enumerate(bucket):
                for b in bucket[i + 1:]:
                    pairs.setdefault((a, b), ri)
    ordered = sorted(pairs, key=lambda p: (pairs[p], p[0], p[1]))

    group_of = {n: n for n in nums}
    group_members = {n: [n] for n in nums}
    group_rules = {n: set() for n in nums}
