def _merged(members, survivor, mem, prec, rule_idx):
    old = members[survivor]
    new = dict(old)
    source = {}

    def first(field):
        for n in prec:
            if members[n][field] != "":
                return members[n][field], n
        return "", None

    if old["name"] == "":
        new["name"], source["name"] = first("name")
    for f in ("email", "phone", "dob"):
        new[f], source[f] = first(f)
    best = None
    for n in prec:
        e = members[n]["expires"]
        if e != "" and (best is None or dates.parse_day(e) > dates.parse_day(members[best]["expires"])):
            best = n
    new["expires"] = members[best]["expires"] if best is not None else ""
    source["expires"] = best
    marks = {members[n]["marketing"] for n in mem}
    new["marketing"] = "no" if "no" in marks else "yes" if "yes" in marks else ""
    new["tags"] = sorted({t for n in mem for t in tag_list(members[n])})
    return {"survivor": survivor, "merged": [n for n in mem if n != survivor], "rules": [RULES[i] for i in rule_idx],
